    deskripsi: 'Mengenal urutan pencernaan makanan serta rantai makanan keseimbangan alam.',
    soal: [
      { id: 'ipas5-1', pertanyaan: 'Organ pertama tempat terjadinya pencernaan mekanik dan kimiawi pada manusia adalah...', pilihan: ['Mulut', 'Lambung', 'Kerongkongan', 'Usus Halus'], jawabanBenar: 0, pembahasan: 'Di mulut gigi mengunyah secara mekanik dan enzim ptialin mencerna secara kimiawi.', kesulitan: 'mudah' },
      { id: 'ipas5-2', pertanyaan: 'Gerakan meremas dan mendorong makanan di kerongkongan menuju lambung disebut...', pilihan: ['Refleks', 'Peristaltik', 'Otomatis', 'Kontraksi statis'], jawabanBenar: 1, pembahasan: 'Gerak peristaltik meremas bergelombang mendorong bolus makanan.', kesulitan: 'mudah' },
      { id: 'ipas5-3', pertanyaan: 'Asam lambung (HCl) berfungsi untuk...', pilihan: ['Mengentalkan darah', 'Menyerap air', 'Membunuh kuman pada makanan', 'Membuat rasa manis'], jawabanBenar: 2, pembahasan: 'Asam klorida (HCl) di lambung mematikan bakteri penyakit dan mengaktifkan pepsin.', kesulitan: 'sedang' },
      { id: 'ipas5-4', pertanyaan: 'Penyerapan sari-sari makanan utama ke dalam pembuluh darah terjadi di...', pilihan: ['Empedu', 'Usus Besar', 'Lambung', 'Usus Halus'], jawabanBenar: 3, pembahasan: 'Vili usus halus menyerap nutrisi ke aliran darah.', kesulitan: 'sedang' },
      { id: 'ipas5-5', pertanyaan: 'Fungsi utama dari usus besar (kolon) adalah...', pilihan: ['Menyerap air dan membusukkan sisa makanan', 'Mencerna protein', 'Menghasilkan enzim amilase', 'Memompa darah'], jawabanBenar: 0, pembahasan: 'Usus besar menyerap kelebihan air dan membusukkan feses dengan bantuan bakteri E. coli.', kesulitan: 'sedang' },
      { id: 'ipas5-6', pertanyaan: 'Dalam rantai makanan ekosistem sawah: Padi -> Belalang -> Katak -> Ular -> Elang. Peran padi adalah sebagai...', pilihan: ['Konsumen I', 'Produsen', 'Pengurai', 'Konsumen puncak'], jawabanBenar: 1, pembahasan: 'Tumbuhan hijau berfotosintesis menghasilkan makanan sendiri sehingga disebut produsen.', kesulitan: 'mudah' },
      { id: 'ipas5-7', pertanyaan: 'Hewan yang memakan hewan lain (pemakan daging) disebut...', pilihan: ['Herbivora', 'Omnivora', 'Karnivora', 'Insektivora saja'], jawabanBenar: 2, pembahasan: 'Karnivora adalah hewan pemakan daging.', kesulitan: 'mudah' },
      { id: 'ipas5-8', pertanyaan: 'Urutan saluran pencernaan manusia yang tepat adalah...', pilihan: ['Mulut -> Lambung -> Kerongkongan -> Usus Halus', 'Mulut -> Tenggorokan -> Lambung', 'Mulut -> Usus Halus -> Lambung -> Anus', 'Mulut -> Kerongkongan -> Lambung -> Usus Halus -> Usus Besar -> Anus'], jawabanBenar: 3, pembahasan: 'Urutan: Mulut -> Kerongkongan -> Lambung -> Usus Halus -> Usus Besar -> Anus.', kesulitan: 'sedang' },
      { id: 'ipas5-9', pertanyaan: 'Organisme yang menguraikan bangkai makhluk hidup menjadi zat hara tanah adalah...', pilihan: ['Pengurai', 'Produsen', 'Konsumen I', 'Parasit'], jawabanBenar: 0, pembahasan: 'Bakteri dan jamur dekomposer menguraikan sisa organisme mati menjadi humus.', kesulitan: 'sedang' },
      { id: 'ipas5-10', pertanyaan: 'Apa yang terjadi pada ekosistem sawah jika populasi ular diburu habis oleh manusia?', pilihan: ['Padi tumbuh semakin lebat', 'Populasi tikus melonjak drastis dan merusak tanaman padi', 'Belalang punah seketika', 'Katak tidak bisa melompat'], jawabanBenar: 1, pembahasan: 'Hilangnya predator ular menyebabkan hama tikus berkembang biak tanpa kendali.', kesulitan: 'tantangan' },
      { id: 'ipas5-11', pertanyaan: 'Urutan organ saluran pencernaan makanan manusia yang benar dari awal hingga akhir adalah...', pilihan: ['Mulut -> Lambung -> Kerongkongan -> Usus halus -> Usus besar -> Anus', 'Mulut -> Tenggorokan -> Lambung -> Usus besar -> Usus halus -> Anus', 'Mulut -> Kerongkongan -> Lambung -> Usus halus -> Usus besar -> Anus', 'Mulut -> Kerongkongan -> Usus halus -> Lambung -> Usus besar -> Anus'], jawabanBenar: 2, pembahasan: 'Makanan masuk melalui mulut, kerongkongan, lambung, usus halus, usus besar, lalu sisa feses keluar lewat anus.', kesulitan: 'mudah' },
      { id: 'ipas5-12', pertanyaan: 'Organ pencernaan yang menghasilkan asam klorida (HCl) untuk membunuh kuman pada makanan adalah...', pilihan: ['Usus besar', 'Mulut', 'Hati', 'Lambung'], jawabanBenar: 3, pembahasan: 'Asam lambung (HCl) mematikan bakteri patogen dan mengaktifkan pepsinogen.', kesulitan: 'mudah' },
      { id: 'ipas5-13', pertanyaan: 'Penyerapan sari-sari makanan ke dalam pembuluh darah terutama terjadi pada bagian...', pilihan: ['Usus halus', 'Usus besar', 'Lambung', 'Kerongkongan'], jawabanBenar: 0, pembahasan: 'Jonjot-jonjot (vili) usus halus menyerap nutrisi makanan yang telah dicerna.', kesulitan: 'mudah' },
      { id: 'ipas5-14', pertanyaan: 'Fungsi utama usus besar dalam sistem pencernaan manusia adalah...', pilihan: ['Mencerna lemak secara kimiawi', 'Menyerap kembali air dan sisa garam mineral', 'Menghasilkan asam klorida', 'Mengunyah makanan secara mekanik'], jawabanBenar: 1, pembahasan: 'Usus besar menyerap kelebihan air sehingga ampas makanan memadat menjadi feses.', kesulitan: 'mudah' },
      { id: 'ipas5-15', pertanyaan: 'Tumbuhan hijau dalam rantai makanan menduduki peran sebagai...', pilihan: ['Konsumen puncak', 'Konsumen tingkat 1', 'Produsen', 'Pengurai'], jawabanBenar: 2, pembahasan: 'Tumbuhan hijau mampu membuat makanan sendiri lewat fotosintesis (autotrof).', kesulitan: 'sedang' },
      { id: 'ipas5-16', pertanyaan: 'Bakteri dan jamur dalam ekosistem bertindak sebagai organisme...', pilihan: ['Karnivora', 'Produsen utama', 'Herbivora', 'Pengurai'], jawabanBenar: 3, pembahasan: 'Pengurai menguraikan zat organik bangkai menjadi mineral hara di dalam tanah.', kesulitan: 'sedang' },
      { id: 'ipas5-17', pertanyaan: 'Peristiwa penguapan air dari permukaan laut, danau, dan sungai akibat panas matahari dinamakan...', pilihan: ['Evaporasi', 'Kondensasi', 'Presipitasi', 'Infiltrasi'], jawabanBenar: 0, pembahasan: 'Evaporasi adalah proses perubahan air cair menjadi uap air ke atmosfer.', kesulitan: 'sedang' },
      { id: 'ipas5-18', pertanyaan: 'Uap air yang naik ke atmosfer mendingin dan berubah menjadi butiran air awan melalui proses...', pilihan: ['Evaporasi', 'Pengembunan', 'Transpirasi', 'Sublimasi'], jawabanBenar: 1, pembahasan: 'Kondensasi membentuk awan ketika uap air mengalami penurunan suhu di atmosfer.', kesulitan: 'sedang' },
      { id: 'ipas5-19', pertanyaan: 'Peristiwa jatuhnya titik-titik air dari awan ke permukaan bumi dinamakan...', pilihan: ['Infiltrasi', 'Evaporasi', 'Presipitasi', 'Transpirasi'], jawabanBenar: 2, pembahasan: 'Presipitasi adalah curah hujan yang turun ke permukaan bumi.', kesulitan: 'sedang' },
      { id: 'ipas5-20', pertanyaan: 'Enzim ptialin (amilase) yang terdapat di dalam rongga mulut berfungsi untuk memecah...', pilihan: ['Kalsium menjadi tulang', 'Protein menjadi asam amino', 'Lemak menjadi asam lemak', 'Zat tepung menjadi zat gula sederhana'], jawabanBenar: 3, pembahasan: 'Enzim amilase ludah menguraikan amilum karbohidrat sejak dari mulut.', kesulitan: 'tantangan' }
    ]
