      { id: 'kod6-2', pertanyaan: 'Sebuah robot diprogram: MAJU 2, BELOK KANAN, MAJU 1. Ini contoh dari konsep...', pilihan: ['Looping tak hingga', 'Sekuensial', 'Bug program', 'Kecerdasan biologis'], jawabanBenar: 1, pembahasan: 'Sekuensial adalah eksekusi perintah baris demi baris berurutan.', kesulitan: 'mudah' },
      { id: 'kod6-3', pertanyaan: 'Perintah logika: "JIKA hari hujan MAKA bawa payung, LAINNYA pakai topi" disebut...', pilihan: ['Bug kompilasi', 'Pengulangan', 'Percabangan', 'Pencarian biner'], jawabanBenar: 2, pembahasan: 'Kondisi If-Else menentukan keputusan program berdasarkan kondisi tertentu.', kesulitan: 'sedang' },
      { id: 'kod6-4', pertanyaan: 'Kecerdasan Buatan (AI) mengenali foto kucing dan anjing melalui proses...', pilihan: ['Menebak acak', 'Mematikan komputer', 'Mencetak ke kertas', 'Melatih model dengan data contoh'], jawabanBenar: 3, pembahasan: 'Machine Learning melatih model AI menggunakan sekumpulan data contoh besar.', kesulitan: 'sedang' },
      { id: 'kod6-5', pertanyaan: 'Jika perintah "LOMPAT" dimasukkan ke blok LOOP 5 kali, robot akan melompat sebanyak...', pilihan: ['5 kali', '1 kali', '10 kali', '0 kali'], jawabanBenar: 0, pembahasan: 'Loop 5 kali mengeksekusi instruksi di dalamnya sebanyak 5 kali berulang.', kesulitan: 'mudah' },
      { id: 'kod6-6', pertanyaan: 'Kesalahan pada penulisan kode yang membuat program tidak berjalan semestinya disebut...', pilihan: ['Byte', 'Bug', 'Bit', 'Chip'], jawabanBenar: 1, pembahasan: 'Bug adalah istilah populer untuk galat atau kesalahan instruksi program.', kesulitan: 'mudah' },
      { id: 'kod6-7', pertanyaan: 'Proses menemukan dan memperbaiki kesalahan (bug) pada program dinamakan...', pilihan: ['Browsing', 'Designing', 'Debugging', 'Downloading'], jawabanBenar: 2, pembahasan: 'Debugging adalah aktivitas melacak dan membetulkan error pada kode.', kesulitan: 'sedang' },
      { id: 'kod6-8', pertanyaan: 'Contoh penerapan Artificial Intelligence (AI) dalam kehidupan sehari-hari anak adalah...', pilihan: ['Menggunting karton', 'Menulis pensil 2B', 'Menyapu lantai lidi', 'Asisten virtual pendeteksi suara'], jawabanBenar: 3, pembahasan: 'Asisten pintar suara memakai pemrosesan bahasa alami (NLP) berbasis AI.', kesulitan: 'sedang' },
      { id: 'kod6-9', pertanyaan: 'Robot di koordinat (0,0) diberi perintah: MAJU Y+2, GESER X+3. Posisi robot sekarang adalah...', pilihan: ['X: 3, Y: 2', 'X: 2, Y: 3', 'X: 1, Y: 1', 'X: 0, Y: 5'], jawabanBenar: 0, pembahasan: 'X bergeser 3 (0+3=3) dan Y bertambah 2 (0+2=2) menjadi (3, 2).', kesulitan: 'sedang' },
      { id: 'kod6-10', pertanyaan: 'Mengapa etika dan kejujuran sangat penting saat menggunakan teknologi AI di sekolah?', pilihan: ['Supaya AI tidak lelah', 'Agar melatih berpikir kritis mandiri dan tidak plagiat tugas', 'Agar baterai awet', 'Karena AI dilarang'], jawabanBenar: 1, pembahasan: 'AI adalah alat bantu belajar pendukung bukan jalan pintas menyontek tanpa berpikir.', kesulitan: 'tantangan' },
      { id: 'koding6-11', pertanyaan: 'Memecah masalah yang rumit menjadi bagian-bagian kecil yang lebih mudah dikelola dalam berpikir komputasional dinamakan...', pilihan: ['Pengenalan pola', 'Abstraksi', 'Dekomposisi', 'Algoritma'], jawabanBenar: 2, pembahasan: 'Dekomposisi mengurai problem besar menjadi sub-komponen terstruktur.', kesulitan: 'mudah' },
      { id: 'koding6-12', pertanyaan: 'Mencari kesamaan, tren, atau keteraturan dalam berbagai masalah dinamakan proses...', pilihan: ['Enkripsi', 'Dekomposisi', 'Debugging', 'Pengenalan pola'], jawabanBenar: 3, pembahasan: 'Mengenali pola membantu menggunakan solusi yang sudah terbukti efektif.', kesulitan: 'mudah' },
      { id: 'koding6-13', pertanyaan: 'Fokus pada informasi esensial dan mengabaikan detail-detail yang tidak penting dinamakan proses...', pilihan: ['Abstraksi', 'Algoritma', 'Dekomposisi', 'Iterasi'], jawabanBenar: 0, pembahasan: 'Abstraksi menyaring aspek krusial tanpa terdistraksi detail remeh.', kesulitan: 'mudah' },
      { id: 'koding6-14', pertanyaan: 'Langkah-langkah logis dan sistematis yang berurutan untuk menyelesaikan suatu masalah dinamakan...', pilihan: ['Hardware', 'Algoritma', 'Database', 'Monitor'], jawabanBenar: 1, pembahasan: 'Algoritma adalah resep instruksi berurutan dalam komputasi.', kesulitan: 'mudah' },
      { id: 'koding6-15', pertanyaan: 'Proses menemukan dan memperbaiki kesalahan (error/bug) dalam program komputer dinamakan...', pilihan: ['Compiling', 'Coding', 'Debugging', 'Browsing'], jawabanBenar: 2, pembahasan: 'Debugging adalah proses pelacakan dan perbaikan bug kode.', kesulitan: 'sedang' },
      { id: 'koding6-16', pertanyaan: 'Perintah logika \'IF - ELSE\' dalam bahasa pemrograman digunakan untuk...', pilihan: ['Mematikan monitor', 'Mengulang instruksi tanpa henti', 'Menyimpan file ke harddisk', 'Mengambil keputusan berdasarkan kondisi'], jawabanBenar: 3, pembahasan: 'Percabangan IF-ELSE menjalankan perintah sesuai terpenuhinya kondisi.', kesulitan: 'sedang' },
      { id: 'koding6-17', pertanyaan: 'Perintah \'LOOP\' atau perulangan dalam pemrograman berguna untuk...', pilihan: ['Menjalankan rangkaian instruksi yang sama berulang kali secara otomatis', 'Menghapus kode yang salah', 'Menggambar garis diagonal', 'Menghubungkan internet'], jawabanBenar: 0, pembahasan: 'Looping mengotomatiskan eksekusi perintah berulang dengan efisien.', kesulitan: 'sedang' },
      { id: 'koding6-18', pertanyaan: 'Teknologi Kecerdasan Buatan (AI) yang mampu mengenali suara ucapan manusia dinamakan...', pilihan: ['Computer Vision', 'Voice Recognition', 'Cloud Backup', 'Robotic Arm'], jawabanBenar: 1, pembahasan: 'Speech recognition memproses gelombang audio suara menjadi teks data.', kesulitan: 'sedang' },
      { id: 'koding6-19', pertanyaan: 'Etika berinternet yang bijak dalam melindungi data pribadi (privasi) adalah...', pilihan: ['Menggunakan password yang sangat mudah ditebak', 'Mengunggah foto kartu identitas ke media sosial', 'Tidak membagikan kata sandi kepada orang asing', 'Membuka link mencurigakan dari spam'], jawabanBenar: 2, pembahasan: 'Menjaga kerahasiaan kata sandi dan identitas melindungi diri dari kejahatan siber.', kesulitan: 'sedang' },
      { id: 'koding6-20', pertanyaan: 'Tindakan menggunakan media digital untuk mengejek, mempermalukan, atau mengancam orang lain dinamakan...', pilihan: ['Digital marketing', 'Coding edukasi', 'Browsing positif', 'Cyberbullying'], jawabanBenar: 3, pembahasan: 'Cyberbullying adalah pelanggaran etika dan hukum yang wajib kita hindari.', kesulitan: 'tantangan' }
