      { id: 'eng2-8', pertanyaan: '"Grandfather" dalam susunan keluarga adalah panggilan untuk...', pilihan: ['Paman', 'Nenek', 'Sepupu', 'Kakek'], jawabanBenar: 3, pembahasan: 'Grandfather artinya kakek.', kesulitan: 'sedang' },
      { id: 'eng2-9', pertanyaan: 'Tempat duduk siswa di kelas dinamakan...', pilihan: ['Chair', 'Desk', 'Whiteboard', 'Window'], jawabanBenar: 0, pembahasan: 'Chair artinya kursi tempat duduk.', kesulitan: 'sedang' },
      { id: 'eng2-10', pertanyaan: 'Lengkapilah kalimat ini: "There are four ... in my family."', pilihan: ['pencils', 'members', 'books', 'doors'], jawabanBenar: 1, pembahasan: 'Four members artinya empat orang anggota dalam keluarga.', kesulitan: 'tantangan' },
      { id: 'eng2-11', pertanyaan: 'Bahasa Inggris untuk benda "PAPAN TULIS" di kelas adalah...', pilihan: ['Book', 'Table', 'Whiteboard', 'Chair'], jawabanBenar: 2, pembahasan: 'Whiteboard adalah papan tulis putih di ruang kelas.', kesulitan: 'mudah' },
      { id: 'eng2-12', pertanyaan: 'Bahasa Inggris dari kata "GUNTING" adalah...', pilihan: ['Pencil', 'Eraser', 'Ruler', 'Scissors'], jawabanBenar: 3, pembahasan: 'Scissors artinya gunting.', kesulitan: 'mudah' },
      { id: 'eng2-13', pertanyaan: 'Angka 11 dalam bahasa Inggris disebut...', pilihan: ['Eleven', 'Ten', 'Twelve', 'Thirteen'], jawabanBenar: 0, pembahasan: 'Eleven adalah angka 11.', kesulitan: 'mudah' },
      { id: 'eng2-14', pertanyaan: 'Angka 12 dalam bahasa Inggris disebut...', pilihan: ['Eleven', 'Twelve', 'Fourteen', 'Fifteen'], jawabanBenar: 1, pembahasan: 'Twelve adalah angka 12.', kesulitan: 'mudah' },
      { id: 'eng2-15', pertanyaan: 'Kata sapaan di pagi hari dalam bahasa Inggris adalah...', pilihan: ['Good night', 'Good afternoon', 'Good morning', 'Good bye'], jawabanBenar: 2, pembahasan: 'Good morning artinya selamat pagi.', kesulitan: 'sedang' },
      { id: 'eng2-16', pertanyaan: '"Sit down, please!" adalah kalimat instruksi yang artinya...', pilihan: ['Silakan berdiri!', 'Silakan baca!', 'Silakan keluar!', 'Silakan duduk!'], jawabanBenar: 3, pembahasan: 'Sit down artinya duduk.', kesulitan: 'sedang' },
      { id: 'eng2-17', pertanyaan: '"Stand up, please!" adalah kalimat instruksi yang artinya...', pilihan: ['Silakan berdiri!', 'Silakan duduk!', 'Silakan lari!', 'Silakan diam!'], jawabanBenar: 0, pembahasan: 'Stand up artinya berdiri.', kesulitan: 'sedang' },
      { id: 'eng2-18', pertanyaan: 'Bahasa Inggris untuk benda "TAS SEKOLAH" adalah...', pilihan: ['Pencil case', 'School bag', 'Ruler', 'Notebook'], jawabanBenar: 1, pembahasan: 'School bag artinya tas sekolah.', kesulitan: 'sedang' },
      { id: 'eng2-19', pertanyaan: '"Show me your pencil!" artinya...', pilihan: ['Beli pensilmu!', 'Patahkan pensilmu!', 'Tunjukkan pensilmu!', 'Buang pensilmu!'], jawabanBenar: 2, pembahasan: 'Show me artinya tunjukkan padaku.', kesulitan: 'sedang' },
      { id: 'eng2-20', pertanyaan: 'Bahasa Inggris untuk "NENEK" dalam keluarga adalah...', pilihan: ['Mother', 'Aunt', 'Sister', 'Grandmother'], jawabanBenar: 3, pembahasan: 'Grandmother artinya nenek.', kesulitan: 'tantangan' }
