      { id: 'pan5-6', pertanyaan: 'Rumah adat suku Dani di pedalaman Papua yang beratap jerami bundar dinamakan...', pilihan: ['Rumah Tongkonan', 'Rumah Honai', 'Rumah Gadang', 'Rumah Betang'], jawabanBenar: 1, pembahasan: 'Rumah Honai berbentuk bulat beratap jerami untuk menghangatkan suhu pegunungan.', kesulitan: 'sedang' },
      { id: 'pan5-7', pertanyaan: 'Keragaman suku bangsa dan budaya yang dimiliki Indonesia merupakan...', pilihan: ['Pemicu perpecahan yang wajib dihilangkan', 'Beban berat negara', 'Kekayaan dan modal kekuatan persatuan bangsa', 'Penghalang kemajuan teknologi'], jawabanBenar: 2, pembahasan: 'Keragaman budaya adalah kekayaan bangsa yang wajib disyukuri dan dirawat.', kesulitan: 'sedang' },
      { id: 'pan5-8', pertanyaan: 'Upacara adat pembakaran jenazah di Pulau Bali dinamakan upacara...', pilihan: ['Grebeg Maulud', 'Rambu Solo', 'Yadnya Kasada', 'Ngaben'], jawabanBenar: 3, pembahasan: 'Ngaben adalah upacara kremasi jenazah umat Hindu di Bali.', kesulitan: 'sedang' },
      { id: 'pan5-9', pertanyaan: 'Sikap yang memandang budayanya sendiri paling hebat dan merendahkan budaya daerah lain disebut...', pilihan: ['Etnosentrisme sempit', 'Nasionalisme tinggi', 'Patriotisme sejati', 'Internasionalisme'], jawabanBenar: 0, pembahasan: 'Etnosentrisme sempit dapat merusak persatuan dan kesatuan nasional.', kesulitan: 'sedang' },
      { id: 'pan5-10', pertanyaan: 'Upaya nyata generasi muda dalam melestarikan budaya nusantara di era digital adalah...', pilihan: ['Mengabaikan seluruh tradisi leluhur', 'Mempelajari kesenian daerah dan mempromosikannya secara kreatif', 'Merasa malu mengenakan pakaian batik', 'Menolak mempelajari lagu nusantara'], jawabanBenar: 1, pembahasan: 'Mempelajari dan mempublikasikan kesenian daerah menjaga warisan bangsa tetap lestari.', kesulitan: 'tantangan' },
      { id: 'pan5-11', pertanyaan: 'Rumah adat tradisional khas masyarakat Minangkabau di Sumatera Barat dinamakan...', pilihan: ['Rumah Tongkonan', 'Rumah Joglo', 'Rumah Gadang', 'Rumah Honai'], jawabanBenar: 2, pembahasan: 'Rumah Gadang memiliki atap lancip bertanduk khas gonjong.', kesulitan: 'mudah' },
      { id: 'pan5-12', pertanyaan: 'Rumah adat Honai dengan atap jerami melingkar berasal dari daerah...', pilihan: ['Kalimantan Barat', 'Aceh', 'Sulawesi Selatan', 'Papua'], jawabanBenar: 3, pembahasan: 'Rumah Honai adalah rumah adat suku Dani di pedalaman Papua.', kesulitan: 'mudah' },
      { id: 'pan5-13', pertanyaan: 'Tari Saman yang dibawakan dengan kekompakan tepukan tangan dan gerak ritmis berasal dari provinsi...', pilihan: ['Aceh', 'Bali', 'Jawa Timur', 'Maluku'], jawabanBenar: 0, pembahasan: 'Tari Saman adalah warisan budaya dunia asal Aceh Gayo.', kesulitan: 'mudah' },
      { id: 'pan5-14', pertanyaan: 'Tari Kecak yang menceritakan epos Ramayana diiringi suara serempak penari berasal dari pulau...', pilihan: ['Lombok', 'Bali', 'Jawa', 'Madura'], jawabanBenar: 1, pembahasan: 'Tari Kecak adalah seni tari pertunjukan legendaris dari Bali.', kesulitan: 'mudah' },
      { id: 'pan5-15', pertanyaan: 'Sikap yang paling tepat dalam menyikapi keberagaman tarian dan adat istiadat suku di Indonesia adalah...', pilihan: ['Menghindari pertemanan beda suku', 'Menganggap suku sendiri paling hebat', 'Bangga, mengapresiasi, dan saling menghormati', 'Mencela kebiasaan daerah lain'], jawabanBenar: 2, pembahasan: 'Keberagaman adat adalah kekayaan khazanah nasional yang patut kita banggakan.', kesulitan: 'sedang' },
      { id: 'pan5-16', pertanyaan: 'Peristiwa Sumpah Pemuda pada 28 Oktober 1928 menegaskan ikrar persatuan bangsa yang terdiri dari...', pilihan: ['Satu agama, satu adat, satu bahasa', 'Satu kekayaan, satu pemimpin, satu partai', 'Satu pulau, satu wilayah, satu suku', 'Satu tanah air, satu bangsa, dan satu bahasa persatuan Indonesia'], jawabanBenar: 3, pembahasan: 'Sumpah Pemuda mengikrarkan kesatuan tumpah darah, bangsa, dan bahasa Indonesia.', kesulitan: 'sedang' },
      { id: 'pan5-17', pertanyaan: 'Pahlawan nasional wanita asal Maluku yang gigih berjuang melawan penjajah Belanda adalah...', pilihan: ['Christina Martha Tiahahu', 'Cut Nyak Dien', 'R.A. Kartini', 'Dewi Sartika'], jawabanBenar: 0, pembahasan: 'Martha Christina Tiahahu adalah srikandi pemberani dari tanah Maluku.', kesulitan: 'sedang' },
      { id: 'pan5-18', pertanyaan: 'Upacara adat Rambu Solo yang menghormati jenazah leluhur berasal dari suku...', pilihan: ['Suku Batak di Sumut', 'Suku Toraja di Sulawesi Selatan', 'Suku Dayak di Kaltim', 'Suku Asmat di Papua'], jawabanBenar: 1, pembahasan: 'Rambu Solo adalah upacara pemakaman adat suku Toraja yang termasyhur.', kesulitan: 'sedang' },
      { id: 'pan5-19', pertanyaan: 'Senjata tradisional khas suku Dayak di Kalimantan yang terkenal adalah...', pilihan: ['Rencong', 'Keris', 'Mandau', 'Kujang'], jawabanBenar: 2, pembahasan: 'Mandau adalah senjata pusaka dan simbol ksatria suku Dayak.', kesulitan: 'sedang' },
      { id: 'pan5-20', pertanyaan: 'Prinsip utama menjaga kerukunan hidup beragama di Indonesia tertuang dalam Undang-Undang Dasar 1945 pasal...', pilihan: ['Pasal 27 ayat 3', 'Pasal 33 ayat 1', 'Pasal 31 ayat 1', 'Pasal 29 ayat 2'], jawabanBenar: 3, pembahasan: 'Pasal 29 ayat (2) menjamin kemerdekaan tiap warga negara memeluk agamanya dan beribadat.', kesulitan: 'tantangan' }
