      { id: 'pai3-3', pertanyaan: 'Shalat fardhu yang dikerjakan sebanyak 4 rakaat pada siang hari adalah shalat...', pilihan: ['Maghrib', 'Subuh', 'Dzuhur', 'Witir'], jawabanBenar: 2, pembahasan: 'Shalat Dzuhur terdiri atas 4 rakaat.', kesulitan: 'mudah' },
      { id: 'pai3-4', pertanyaan: 'Membaca Surat Al-Fatihah dalam setiap rakaat shalat hukumnya...', pilihan: ['Batal', 'Sunnah biasa', 'Makruh', 'Rukun shalat'], jawabanBenar: 3, pembahasan: 'Membaca Al-Fatihah adalah rukun shalat yang wajib dipenuhi.', kesulitan: 'mudah' },
      { id: 'pai3-5', pertanyaan: 'Syarat sah shalat sebelum memulainya adalah bersuci dari hadas dengan cara...', pilihan: ['Berwudhu dengan air suci menyucikan', 'Mencuci kaki saja', 'Mengelap wajah dengan tisu', 'Mandi kering'], jawabanBenar: 0, pembahasan: 'Wudhu menghilangkan hadas kecil sebelum shalat.', kesulitan: 'mudah' },
      { id: 'pai3-6', pertanyaan: 'Sifat mustahil bagi Allah adalah sifat yang...', pilihan: ['Pasti dimiliki Allah', 'Tidak mungkin ada pada diri Allah SWT', 'Boleh ada boleh tidak', 'Dimiliki para malaikat'], jawabanBenar: 1, pembahasan: 'Sifat mustahil mustahil dimiliki Allah SWT (lawan sifat wajib).', kesulitan: 'sedang' },
      { id: 'pai3-7', pertanyaan: 'Shalat fardhu yang diawali dengan doa qunut pada waktu subuh berjumlah... rakaat.', pilihan: ['4 rakaat', '3 rakaat', '2 rakaat', '1 rakaat'], jawabanBenar: 2, pembahasan: 'Shalat Subuh berjumlah 2 rakaat.', kesulitan: 'sedang' },
      { id: 'pai3-8', pertanyaan: 'Arah kiblat bagi umat Islam saat mendirikan shalat menghadap ke...', pilihan: ['Arah angin', 'Kutub utara', 'Arah matahari terbenam', 'Ka\'bah di Masjidil Haram Makkah'], jawabanBenar: 3, pembahasan: 'Menghadap Ka\'bah di Baitullah Makkah adalah syarat sah shalat.', kesulitan: 'sedang' },
      { id: 'pai3-9', pertanyaan: 'Malaikat yang bertugas menyampaikan wahyu kepada para rasul adalah Malaikat...', pilihan: ['Jibril', 'Mikail', 'Israfil', 'Izrail'], jawabanBenar: 0, pembahasan: 'Malaikat Jibril bertugas menyampaikan wahyu kebenaran Ilahi.', kesulitan: 'sedang' },
      { id: 'pai3-10', pertanyaan: 'Hikmah utama menjalankan shalat lima waktu tepat pada waktunya adalah...', pilihan: ['Supaya mendapat pujian tetangga', 'Mencegah perbuatan keji dan munkar serta hati tenteram', 'Menghabiskan waktu', 'Agar boleh bermalas-malasan'], jawabanBenar: 1, pembahasan: 'Innash shalata tanha \'anil fahsya-i wal munkar (Shalat mencegah perbuatan keji dan mungkar).', kesulitan: 'tantangan' },
      { id: 'pai3-11', pertanyaan: 'Sifat wajib "Baqa" bagi Allah artinya Allah Maha...', pilihan: ['Fana hancur', 'Berubah bentuk', 'Kekal abadi selamanya', 'Tertidur'], jawabanBenar: 2, pembahasan: 'Baqa artinya Allah Maha Kekal abadi, tidak akan pernah binasa.', kesulitan: 'mudah' },
      { id: 'pai3-12', pertanyaan: 'Shalat fardhu yang dikerjakan saat matahari terbenam berjumlah 3 rakaat adalah...', pilihan: ['Dzuhur', 'Isya', 'Ashar', 'Maghrib'], jawabanBenar: 3, pembahasan: 'Shalat Maghrib berjumlah 3 rakaat di awal malam.', kesulitan: 'mudah' },
      { id: 'pai3-13', pertanyaan: 'Gerakan sujud dalam shalat dilakukan dengan meletakkan dahi, kedua hidung, telapak tangan, lutut, dan jemari kaki ke...', pilihan: ['Sajadah', 'Dinding', 'Pundak teman', 'Atas meja'], jawabanBenar: 0, pembahasan: 'Sujud menempelkan 7 anggota sujud ke tempat shalat dengan tuma\'ninah.', kesulitan: 'mudah' },
      { id: 'pai3-14', pertanyaan: 'Malaikat yang bertugas membagikan rezeki dan menurunkan air hujan adalah Malaikat...', pilihan: ['Izrail', 'Mikail', 'Munkar', 'Nakir'], jawabanBenar: 1, pembahasan: 'Malaikat Mikail bertugas mengatur pembagian rezeki dan hujan atas izin Allah.', kesulitan: 'mudah' },
      { id: 'pai3-15', pertanyaan: 'Menjaga pandangan dan lisan dari menggunjing orang lain disebut perilaku...', pilihan: ['Riya', 'Mazmumah', 'Mahmudah', 'Kufur'], jawabanBenar: 2, pembahasan: 'Akhlak mahmudah adalah budi pekerti yang luhur dan diridhai Allah.', kesulitan: 'sedang' },
      { id: 'pai3-16', pertanyaan: 'Tuma\'ninah dalam shalat artinya...', pilihan: ['Menoleh ke kanan kiri', 'Bergerak cepat terburu-buru', 'Membaca dengan teriak', 'Berhenti sejenak dan tenang di setiap gerakan'], jawabanBenar: 3, pembahasan: 'Tuma\'ninah adalah diam sejenak sekadar bacaan tasbih agar shalat khusyuk.', kesulitan: 'sedang' },
      { id: 'pai3-17', pertanyaan: 'Nabi yang diberi mukjizat selamat dari kobaran api raja Namrud adalah Nabi...', pilihan: ['Ibrahim AS', 'Musa AS', 'Isa AS', 'Yusuf AS'], jawabanBenar: 0, pembahasan: 'Allah menyelamatkan Nabi Ibrahim AS dengan mendinginkan api yang membakarnya.', kesulitan: 'sedang' },
      { id: 'pai3-18', pertanyaan: 'Batas aurat bagi anak laki-laki saat shalat adalah antara...', pilihan: ['Leher sampai dada', 'Pusar sampai lutut', 'Ujung rambut sampai kaki', 'Tangan saja'], jawabanBenar: 1, pembahasan: 'Aurat dasar laki-laki saat shalat tertutup antara pusar hingga bawah lutut.', kesulitan: 'sedang' },
      { id: 'pai3-19', pertanyaan: 'Shalat berjamaah bersama imam di masjid memiliki keutamaan pahala dibanding shalat munfarid (sendirian) sebesar...', pilihan: ['5 derajat', '2 derajat', '27 derajat kebaikan', '10 derajat'], jawabanBenar: 2, pembahasan: 'Shalat jamaah lebih utama 27 derajat dibanding shalat sendirian.', kesulitan: 'sedang' },
      { id: 'pai3-20', pertanyaan: 'Pentingnya sikap tawakal setelah kita berikhtiar dan berdoa sungguh-sungguh adalah...', pilihan: ['Putus asa bila gagal', 'Menyerah tanpa usaha', 'Menyalahkan takdir', 'Menerima ketetapan terbaik dari Allah dengan lapang dada'], jawabanBenar: 3, pembahasan: 'Tawakal berserah diri kepada Allah setelah berusaha sekuat tenaga.', kesulitan: 'tantangan' }
