      { id: 'pjk3-2', pertanyaan: 'Contoh gerak manipulatif dalam permainan kasti adalah...', pilihan: ['Berdiri diam di pos', 'Melempar dan memukul bola', 'Tidur di rumput', 'Membaca buku'], jawabanBenar: 1, pembahasan: 'Melempar, menangkap, dan memukul bola adalah manipulatif.', kesulitan: 'mudah' },
      { id: 'pjk3-3', pertanyaan: 'Bagian kaki yang paling tepat digunakan untuk mengoper bola jarak pendek dalam sepak bola adalah...', pilihan: ['Lutut atas', 'Tumit belakang', 'Kaki bagian dalam', 'Jari kelingking'], jawabanBenar: 2, pembahasan: 'Kaki bagian dalam memberikan akurasi operan yang terarah.', kesulitan: 'mudah' },
      { id: 'pjk3-4', pertanyaan: 'Sebelum melakukan olahraga lari atau bermain bola, kita wajib melakukan...', pilihan: ['Minum es batu banyak', 'Makan kenyang', 'Tidur siang', 'Pemanasan'], jawabanBenar: 3, pembahasan: 'Pemanasan mencegah cedera otot dan menyiapkan detak jantung.', kesulitan: 'mudah' },
      { id: 'pjk3-5', pertanyaan: 'Menangkap bola melambung tinggi di udara membutuhkan konsentrasi pandangan mata ke arah...', pilihan: ['Datangnya bola', 'Kaki teman', 'Penonton di tribun', 'Awan di langit'], jawabanBenar: 0, pembahasan: 'Pandangan mata harus fokus mengikuti arah bola yang melayang.', kesulitan: 'mudah' },
      { id: 'pjk3-6', pertanyaan: 'Permainan kasti dimainkan oleh dua regu yaitu regu pemukul dan regu...', pilihan: ['Wasit', 'Penjaga', 'Suporter', 'Pelatih'], jawabanBenar: 1, pembahasan: 'Dua regu dalam kasti adalah regu pemukul dan regu penjaga.', kesulitan: 'sedang' },
      { id: 'pjk3-7', pertanyaan: 'Gerak lokomotor yang berpindah tempat dalam sepak bola contohnya adalah...', pilihan: ['Menekuk lutut diam', 'Mengayun tangan di tempat', 'Berlari menggiring bola', 'Duduk istirahat'], jawabanBenar: 2, pembahasan: 'Berlari berpindah tempat adalah gerak lokomotor.', kesulitan: 'sedang' },
      { id: 'pjk3-8', pertanyaan: 'Setelah selesai berolahraga, kita melakukan pendinginan (cooling down) yang bertujuan untuk...', pilihan: ['Menambah lelah', 'Membuat kram otot', 'Menghabiskan tenaga', 'Menurunkan suhu tubuh dan memulihkan otot perlahan'], jawabanBenar: 3, pembahasan: 'Pendinginan mengembalikan detak jantung dan merilekskan otot.', kesulitan: 'sedang' },
      { id: 'pjk3-9', pertanyaan: 'Alat pemukul dalam permainan kasti terbuat dari...', pilihan: ['Kayu yang kuat dan halus', 'Besi baja tajam', 'Kaca bening', 'Batu kali'], jawabanBenar: 0, pembahasan: 'Tongkat pemukul kasti dibuat dari kayu yang aman dan kokoh.', kesulitan: 'sedang' },
      { id: 'pjk3-10', pertanyaan: 'Sikap sportif saat bermain olahraga tim tercermin dari...', pilihan: ['Menyalahkan teman jika kalah', 'Menghormati keputusan wasit dan bekerja sama kompak', 'Bermain kasar untuk mencederai lawan', 'Menolak berjabat tangan'], jawabanBenar: 1, pembahasan: 'Sportivitas menjunjung tinggi kejujuran, kerja sama, dan persaudaraan.', kesulitan: 'tantangan' },
      { id: 'pjk3-11', pertanyaan: 'Menendang bola ke arah gawang lawan dengan tujuan mencetak poin gol disebut teknik...', pilihan: ['Membuang bola', 'Menjaga pos', 'Menembak bola', 'Lemparan ke dalam'], jawabanBenar: 2, pembahasan: 'Shooting adalah tendangan terarah ke sasaran gawang lawan.', kesulitan: 'mudah' },
      { id: 'pjk3-12', pertanyaan: 'Pemain sepak bola yang bertugas khusus menjaga gawang dan boleh memakai tangan adalah...', pilihan: ['Gelandang tengah', 'Penyerang', 'Bek bertahan', 'Penjaga gawang'], jawabanBenar: 3, pembahasan: 'Kiper bertugas menghadang bola masuk ke gawang dengan anggota tubuh termasuk tangan di area kotak penalti.', kesulitan: 'mudah' },
      { id: 'pjk3-13', pertanyaan: 'Gerak memantul-mantulkan bola basket ke lantai sambil berjalan disebut...', pilihan: ['Dribbling', 'Passing', 'Smash', 'Heading'], jawabanBenar: 0, pembahasan: 'Dribbling adalah gerakan menggiring bola basket memantul ke lantai.', kesulitan: 'mudah' },
      { id: 'pjk3-14', pertanyaan: 'Untuk melatih kelenturan persendian tubuh, gerakan senam yang tepat adalah...', pilihan: ['Mengangkat beban sangat berat', 'Mencium lutut dan meliukkan pinggang perlahan', 'Melompat tanpa aturan', 'Duduk membungkuk lama'], jawabanBenar: 1, pembahasan: 'Peregangan meliukkan pinggang dan mencium lutut melenturkan sendi dan otot.', kesulitan: 'mudah' },
      { id: 'pjk3-15', pertanyaan: 'Manfaat menjaga kebersihan pakaian olahraga setelah dipakai berkeringat adalah...', pilihan: ['Supaya bau keringat tahan lama', 'Agar pakaian menjadi sempit', 'Mencegah timbulnya gatal-gatal dan kuman penyakit kulit', 'Menghabiskan detergen'], jawabanBenar: 2, pembahasan: 'Pakaian olahraga harus segera dicuci bersih agar terbebas dari jamur dan bakteri.', kesulitan: 'sedang' },
      { id: 'pjk3-16', pertanyaan: 'Dalam permainan kasti, pelambung bola melempar bola ke arah pemukul dengan ayunan tangan dari...', pilihan: ['Kaki', 'Atas kepala membanting keras', 'Belakang tubuh sembunyi', 'Bawah ke atas secara lembut sesuai permintaan pemukul'], jawabanBenar: 3, pembahasan: 'Pelambung melambungkan bola dari bawah dengan ramah dan terarah.', kesulitan: 'sedang' },
      { id: 'pjk3-17', pertanyaan: 'Olahraga teratur minimal 30 menit sehari bermanfaat untuk...', pilihan: ['Menyehatkan jantung dan meningkatkan daya tahan tubuh', 'Membuat tulang rapuh', 'Membuat malas belajar', 'Menambah berat badan berlebih'], jawabanBenar: 0, pembahasan: 'Olahraga rutin menguatkan kerja jantung, paru-paru, dan imunitas.', kesulitan: 'sedang' },
      { id: 'pjk3-18', pertanyaan: 'Mencuci tangan dengan air mengalir dan sabun paling penting dilakukan...', pilihan: ['Saat sedang tidur', 'Sebelum makan dan setelah beraktivitas luar ruangan', 'Hanya di hari libur', 'Setahun sekali'], jawabanBenar: 1, pembahasan: 'Cuci tangan pakai sabun membunuh kuman penyakit secara efektif.', kesulitan: 'sedang' },
      { id: 'pjk3-19', pertanyaan: 'Pola makan bergizi seimbang mencakup makanan pokok, lauk pauk, sayuran, dan...', pilihan: ['Minuman bersoda', 'Permen manis berwarna', 'Buah-buahan segar serta air putih cukup', 'Makanan berpengawet'], jawabanBenar: 2, pembahasan: 'Makanan bergizi memenuhi pedoman gizi seimbang untuk pertumbuhan anak.', kesulitan: 'sedang' },
      { id: 'pjk3-20', pertanyaan: 'Apa yang harus dilakukan jika ada teman yang terkilir atau cedera saat bermain olahraga di lapangan?', pilihan: ['Meninggalkannya sendirian', 'Menertawakannya ramai-ramai', 'Memaksanya terus berlari', 'Menolongnya segera, mengompres dingin, dan lapor ke guru olahraga/UKS'], jawabanBenar: 3, pembahasan: 'Pertolongan pertama pada cedera dan memanggil bantuan guru/UKS adalah sikap tanggap peduli sesama.', kesulitan: 'tantangan' }
