      { id: 'pai5-3', pertanyaan: 'Kitab suci Injil diturunkan oleh Allah SWT kepada Nabi...', pilihan: ['Ismail AS', 'Ibrahim AS', 'Isa AS', 'Yahya AS'], jawabanBenar: 2, pembahasan: 'Kitab Injil diturunkan kepada Nabi Isa AS sebagai petunjuk bagi Bani Israil.', kesulitan: 'mudah' },
      { id: 'pai5-4', pertanyaan: 'Puasa menurut bahasa artinya menahan diri, sedangkan menurut istilah syariat adalah menahan diri dari...', pilihan: ['Berbicara dengan orang lain', 'Tidur siang hari', 'Membaca buku', 'Makan, minum, dan hal yang membatalkan puasa dari terbit fajar hingga terbenam matahari'], jawabanBenar: 3, pembahasan: 'Puasa Ramadhan wajib menahan diri dari terbit fajar shadiq hingga adzan maghrib tiba.', kesulitan: 'mudah' },
      { id: 'pai5-5', pertanyaan: 'Waktu sahur dianjurkan diakhiri menjelang masuk waktu subuh yang dinamakan waktu...', pilihan: ['Imsak', 'Isyraq', 'Dhuha', 'Tenggelam matahari'], jawabanBenar: 0, pembahasan: 'Waktu imsak adalah tanda kehati-hatian 10 menit sebelum adzan subuh berkumandang.', kesulitan: 'mudah' },
      { id: 'pai5-6', pertanyaan: 'Al-Qur\'an diturunkan sebagai penyempurna dan membenarkan kitab-kitab suci terdahulu disebut peran...', pilihan: ['Pesaing', 'Al-Muhaimin', 'Pengganti sementara', 'Buku biasa'], jawabanBenar: 1, pembahasan: 'Al-Qur\'an menjaga kemurnian wahyu Ilahi dan menghapus hukum syariat terdahulu.', kesulitan: 'sedang' },
      { id: 'pai5-7', pertanyaan: 'Malam kemuliaan yang lebih baik dari seribu bulan di bulan suci Ramadhan adalah malam...', pilihan: ['Nuzulul Kitab', 'Isra Mi\'raj', 'Lailatul Qadar', 'Tahun Baru'], jawabanBenar: 2, pembahasan: 'Lailatul Qadar bernilai pahala ibadah lebih dari 1000 bulan (Surat Al-Qadr).', kesulitan: 'sedang' },
      { id: 'pai5-8', pertanyaan: 'Sikap toleran menghormati teman yang sedang berpuasa di sekolah dicerminkan dengan...', pilihan: ['Memaksanya batal', 'Mengejek teman yang lapar', 'Menawarkan makanan berkali-kali', 'Tidak makan dan minum di depan teman yang berpuasa secara sengaja'], jawabanBenar: 3, pembahasan: 'Saling menghormati ibadah teman memperkuat kerukunan dan persaudaraan sejati.', kesulitan: 'sedang' },
      { id: 'pai5-9', pertanyaan: 'Zakat mal (zakat harta kekayaan) dikeluarkan oleh seorang muslim yang hartanya telah mencapai...', pilihan: ['Mencapai batas nisab dan satu tahun', 'Utang menumpuk', 'Usia 100 tahun', 'Jumlah barang sedikit'], jawabanBenar: 0, pembahasan: 'Nisab adalah batas minimal kepemilikan harta yang wajib dizakati.', kesulitan: 'sedang' },
      { id: 'pai5-10', pertanyaan: 'Hikmah spiritual dan sosial dari ibadah puasa Ramadhan adalah...', pilihan: ['Hanya untuk menurunkan berat badan', 'Melatih ketakwaan, mengasah empati merasakan lapar kaum dhuafa, dan menyehatkan jasmani', 'Agar boleh bermalas-malasan siang hari', 'Menghindari tugas sekolah'], jawabanBenar: 1, pembahasan: 'Puasa menumbuhkan kepekaan sosial, kejujuran batin, dan disiplin tinggi.', kesulitan: 'tantangan' },
      { id: 'pai5-11', pertanyaan: 'Bahasa asli yang digunakan dalam Kitab Suci Al-Qur\'an adalah bahasa...', pilihan: ['Suryani', 'Ibrani', 'Arab', 'Yunani'], jawabanBenar: 2, pembahasan: 'Al-Qur\'an diturunkan dalam bahasa Arab yang fasih dan sarat balaghah sastra tinggi.', kesulitan: 'mudah' },
      { id: 'pai5-12', pertanyaan: 'Peristiwa pertama kali diturunkannya wahyu Al-Qur\'an kepada Nabi Muhammad SAW di Gua Hira dinamakan...', pilihan: ['Fathu Makkah', 'Maulid Nabi', 'Hijrah', 'Nuzulul Qur\'an'], jawabanBenar: 3, pembahasan: 'Nuzulul Qur\'an diperingati pada tanggal 17 Ramadhan diawali turunnya Surat Al-\'Alaq 1-5.', kesulitan: 'mudah' },
      { id: 'pai5-13', pertanyaan: 'Hal yang membatalkan puasa di bawah ini adalah...', pilihan: ['Makan dan minum secara sengaja di siang hari', 'Lupa meminum air seteguk', 'Tidur di siang hari', 'Mandi dengan air bersih'], jawabanBenar: 0, pembahasan: 'Makan atau minum dengan sengaja membatalkan puasa, sedangkan jika lupa dimaafkan.', kesulitan: 'mudah' },
      { id: 'pai5-14', pertanyaan: 'Orang yang sakit parah atau musafir dalam perjalanan jauh diperbolehkan tidak berpuasa dengan syarat...', pilihan: ['Membayar denda uang jutaan', 'Mengganti puasa di hari lain', 'Meninggalkan shalat', 'Tidak perlu berbuat apa-apa'], jawabanBenar: 1, pembahasan: 'Rukhsah keringanan bagi orang sakit/musafir adalah mengqadha di bulan lain.', kesulitan: 'mudah' },
      { id: 'pai5-15', pertanyaan: 'Sikap gemar bersedekah dan membantu meringankan penderitaan orang lain disebut...', pilihan: ['Takabur', 'Bakhil', 'Dermawan', 'Kikir'], jawabanBenar: 2, pembahasan: 'Kedermawanan adalah sifat mulia yang dicintai Allah dan sesama manusia.', kesulitan: 'sedang' },
      { id: 'pai5-16', pertanyaan: 'Sahabat Nabi Muhammad SAW yang mendapat gelar "As-Siddiq" karena senantiasa membenarkan ajaran Rasulullah adalah...', pilihan: ['Ali bin Abi Thalib RA', 'Umar bin Khattab RA', 'Utsman bin Affan RA', 'Abu Bakar Ash-Shiddiq RA'], jawabanBenar: 3, pembahasan: 'Abu Bakar RA adalah sahabat terdekat yang membenarkan peristiwa Isra Mi\'raj tanpa ragu.', kesulitan: 'sedang' },
      { id: 'pai5-17', pertanyaan: 'Doa berbuka puasa diucapkan sebagai wujud...', pilihan: ['Rasa syukur kepada Allah SWT atas nikmat rezeki dan tuntasnya ibadah puasa', 'Kemenangan perang', 'Keluh kesah karena haus', 'Permintaan hadiah'], jawabanBenar: 0, pembahasan: 'Berbuka dengan kurma manis dan bersyukur melipatgandakan pahala kebaikan.', kesulitan: 'sedang' },
      { id: 'pai5-18', pertanyaan: 'Membaca Al-Qur\'an secara tartil di malam-malam bulan Ramadhan bersama-sama dinamakan...', pilihan: ['Qasidah', 'Tadarus Al-Qur\'an', 'Iktikaf diam', 'Hafalan bisik'], jawabanBenar: 1, pembahasan: 'Tadarus membaca, menyimak, dan mentadaburi ayat suci Al-Qur\'an.', kesulitan: 'sedang' },
      { id: 'pai5-19', pertanyaan: 'Golongan orang yang berhak menerima zakat (Mustahiq) terdiri atas... asnaf.', pilihan: ['5 Asnaf', '3 Asnaf', '8 Asnaf', '12 Asnaf'], jawabanBenar: 2, pembahasan: 'Delapan golongan penerima zakat diatur tegas dalam Surat At-Taubah ayat 60.', kesulitan: 'sedang' },
      { id: 'pai5-20', pertanyaan: 'Mengapa menjaga lisan dari perkataan dusta, fitnah, dan mencela merupakan syarat kesempurnaan pahala puasa?', pilihan: ['Agar tidak perlu berbicara lagi', 'Supaya tidak aus suaranya', 'Biar cepat mengantuk', 'Karena Rasulullah bersabda banyak orang berpuasa hanya mendapat lapar dan dahaga akibat lisannya'], jawabanBenar: 3, pembahasan: 'Puasa hakiki adalah menahan seluruh anggota badan dan hawa nafsu dari perbuatan maksiat.', kesulitan: 'tantangan' }
